66	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
67	        if (sheet.isArchived()) {
68	            throw new SheetArchivedException();
69	        }
70	        if (!roles.isSteward(id, user)) {
71	            throw new ActionNotAllowedException("archive the sheet");
