267	    /** Change the sheet's parent (none: no parent), recording the figures it moves. Not dated. The sheet
268	     *  cannot be its own parent, nor name a sheet that has it as an ancestor, and the parent must exist. */
269	    @Transactional
270	    public Sheet setParent(String id, String user, String parent) {
271	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
272	        String p = parent == null || parent.isBlank() ? null : parent.trim();
273	        if (p != null) {
274	            if (p.equals(id)) {
275	                throw new ParentRefusedException("A sheet cannot be its own parent.");
276	            }
277	            if (!sheets.existsById(p)) {
278	                throw new ParentRefusedException("The parent must be a sheet that has been loaded.");
279	            }
280	            if (hasAncestor(p, id)) {
281	                throw new ParentRefusedException("The parent cannot be a sheet that has this sheet as an ancestor.");
282	            }
283	        }
284	        Rollup.Snapshot before = rollup.take(id);
285	        sheet.setParent(p);
286	        sheets.saveAndFlush(sheet);
287	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=parent value="
288	                + (p == null ? "" : p));
289	        rollup.recordChanges(id, user, before);
290	        return sheet;
291	    }
292	
293	    /** Whether a sheet has another among all its ancestors, however far up. */
294	    private boolean hasAncestor(String id, String ancestor) {
295	        Set<String> seen = new HashSet<>();
296	        String at = sheets.findById(id).map(Sheet::getParent).orElse(null);
297	        while (at != null && seen.add(at)) {
298	            if (at.equals(ancestor)) {
299	                return true;
300	            }
301	            at = sheets.findById(at).map(Sheet::getParent).orElse(null);
302	        }
303	        return false;
304	    }
