309	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
310	        sheet.setEntryDate(entryDate);
311	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=entry-date value="
312	                + (entryDate == null ? "" : entryDate.toString()));
313	        return sheet;
314	    }
315	
316	    /** Change the sheet's period numbering from-date (none: off). */
317	    @Transactional
318	    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
319	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
320	        sheet.setPeriodNumberingFrom(from);
321	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
322	                + (from == null ? "" : from.toString()));
323	        return sheet;
324	    }
325	
326	    /** The sheet's next settle batch number (1, 2, ...). None is ever given twice. */
327	    @Transactional
328	    public int nextSettleBatch(String id) {
329	        return sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new).nextSettleBatch();
330	    }
331	
332	    /** The next number for a claim due by a date: while the sheet numbers by period, the next in the
333	     *  sequence of the period containing the date (<period name>-1, -2, ...), or of no period (X-1, ...);
334	     *  otherwise the sheet-wide one (1, 2, ...). None is ever given twice. */
335	    @Transactional
336	    public String nextClaimNumber(String id, LocalDate date) {
337	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
338	        if (!sheet.numbersByPeriod()) {
339	            return sheet.nextClaimNumber();
340	        }
341	        String prefix = periodPrefix(id, date);
342	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(id, prefix)
343	                .orElseGet(() -> new ClaimSequence(id, prefix));
344	        String number = sequence.nextClaimNumber();
345	        sequences.save(sequence);
346	        return number;
347	    }
348	
349	    /** The prefix of the numbering sequence of a date: the name of the period containing it, else X. */
350	    private String periodPrefix(String id, LocalDate date) {
351	        return periods.findBySheetIdOrderByFromDateAsc(id).stream()
352	                .filter(p -> p.contains(date)).findFirst().map(Period::getName).orElse("X");
353	    }
354	}
