-- V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(200) PRIMARY KEY,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
-- V2__sheet_today.sql
-- The sheet's "today": every date decision and default date in the sheet uses it, never the real
-- clock. A sheet starts on the real date it was first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- V3__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case. Names are stored
-- trimmed; name_key is the name as compared, and the index refuses a second person with it.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- V6__rate.sql
-- The sheet's rate for each grade: a percent (0.00 or more, two decimals). A grade with no row has
-- no rate.
CREATE TABLE rate (
    id       BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    rate     DECIMAL(9, 2) NOT NULL CHECK (rate >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- V7__claim_status.sql
-- A claim's status: DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), no gaps and never
-- reused. A draft has none; voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, claim_number);
-- V9__claim_settled_due.sql
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate at
-- that moment, divided by 100, rounded half up to cents. None while DRAFT or OPEN, and none when
-- the grade had no rate then (such a claim's due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(15, 2);
-- V10__rate_from.sql
-- A rate can carry a from-date: a grade may have several rates, and a claim uses the one whose
-- from-date is the latest on or before its date. A rate with no from-date applies from the
-- beginning of time. A grade has at most one rate per from-date (and one with none).
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
-- V11__claim_opened_by.sql
-- Who opened a claim: the signed-in user who moved it from DRAFT to OPEN. None while a draft. That
-- user cannot settle it (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(200);
-- V12__person_version.sql
-- The version of a person, moved on by each save, so an editor opened on an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
-- V13__statement.sql
-- A statement taken of a person: the sheet's today when it was taken, the person's due-total then
-- (none when it showed n/a) and how many of their claims counted. Listed in the order taken (by id).
CREATE TABLE statement (
    id          BIGINT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id    VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id   BIGINT         NOT NULL REFERENCES person (id),
    taken_on    DATE           NOT NULL,
    due_total   DECIMAL(15, 2),
    claim_count INT            NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);

-- A claim bound by its person's last statement shows and totals the figure it had then (none when
-- that was n/a), whatever later rate or grade changes would make it, until the next statement.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
-- V14__period.sql
-- A period on the sheet: a name, unique on the sheet without regard to case, and a from and to date,
-- both inclusive. No two of a sheet's periods overlap (the service refuses one that would).
CREATE TABLE period (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200)  NOT NULL,
    name_key  VARCHAR(200)  GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE          NOT NULL,
    to_date   DATE          NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
-- V15__period_closed.sql
-- A period can be closed: its due-total is then fixed at the figure it had when closed, and no claim
-- dated inside it can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
-- V16__claim_void_keeps_number.sql
-- A voided claim now keeps the number it was given when opened (still never reused); only a draft
-- has none. Only a DRAFT claim can be edited. No change to the columns is needed.
SELECT 1;
-- V17__person_retired.sql
-- The date a person is retired from; null while they are not retired. A person with one set counts as
-- retired at once, whatever the date; a claim dated after it is refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- V18__person_held.sql
-- Whether a person is on hold: while held, their OPEN claims count in no live total; SETTLED ones still do.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- V19__roles_clerk_limit.sql
-- The sheet's clerk limit: the largest due a clerk may settle (two decimals); none means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2) CHECK (clerk_limit >= 0);

-- The role the sheet gives a user name: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200)  NOT NULL,
    role      VARCHAR(20)   NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
-- V20__sheet_floor.sql
-- The sheet's floor: the least a claim's live due can be (two decimals). A sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
-- V21__sheet_terms.sql
-- The sheet's terms: the number of days after a claim's date it is due by. A sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL CHECK (terms >= 0);
-- V22__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days
-- it is overdue. A sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(9, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
-- V23__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    id        BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_unique ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id);
-- V24__person_grade.sql
-- A person's grade is dated: each grade they are given applies from a date, the first from the
-- beginning of time (no from-date). On a date the grade in force is the one whose from-date is the
-- latest on or before it. A person has at most one grade per from-date (and one with none).
CREATE TABLE person_grade (
    id        BIGINT     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
-- V25__claim_correction.sql
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the same
-- person that it corrects. The amount's old check (0.00 or more) goes with its column; any other
-- claim names none.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(15, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD COLUMN corrects_number INTEGER;
ALTER TABLE claim ADD CONSTRAINT claim_correction CHECK ((amount < 0) = (corrects_number IS NOT NULL));
-- V26__sheet_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds half up, on or after it half to even. None
-- (blank) means the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- V27__period_numbering.sql
-- The sheet's period numbering from-date: while set and the sheet's today is on or after it, a claim
-- opened is numbered within its period (<period name>-<n>), or X-<n> when in no period. None (blank)
-- means off: claims take the sheet-wide number (1, 2, ...), which continues where it left off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number, and the number a correction names, are now text: a sheet-wide number or a
-- period number.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects_number SET DATA TYPE VARCHAR(220);
-- The last number given in each numbering sequence of a sheet other than the sheet-wide one: one per
-- prefix (a period's name, or X for claims in no period).
CREATE TABLE claim_sequence (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    prefix      VARCHAR(200) NOT NULL,
    last_number INT          NOT NULL
);
CREATE UNIQUE INDEX claim_sequence_prefix ON claim_sequence (sheet_id, prefix);
-- V28__claim_pending.sql
-- A clerk settling a claim whose due is above the clerk limit now puts it PENDING: a steward approves
-- it (SETTLED) or rejects it (back to OPEN), and it can be voided. The status check is re-made with it.
ALTER TABLE claim ALTER COLUMN status RENAME TO status_old;
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET status = status_old;
ALTER TABLE claim DROP COLUMN status_old;
-- V29__claim_list_order.sql
-- A claim's place in its sheet's list, newest first: the next on the sheet when it is added, and again
-- when it is reassigned to another person, so a moved claim is listed as its new person's newest
-- whatever its date. Existing claims keep the order they were added in.
ALTER TABLE claim ADD COLUMN list_order BIGINT;
UPDATE claim SET list_order = id;
ALTER TABLE claim ALTER COLUMN list_order SET NOT NULL;
CREATE INDEX claim_list_order ON claim (sheet_id, list_order);
-- V30__grade_terms_claim_due_by.sql
-- Terms per grade: a grade with its own terms has its claims due that many days after their date; a grade
-- without uses the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    terms    INT          NOT NULL CHECK (terms >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by is fixed when it is added: its date plus the terms of its person's grade then in force.
-- Existing claims take their date plus their sheet's terms now.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- V31__claim_status_log.sql
-- Each claim's status log: one line per status it has had, oldest first, with who made the change, the
-- sheet's today then, and the claim's due as it was computed at that moment (none when it was n/a).
-- Existing claims start with no lines.
CREATE TABLE claim_status_log (
    claim_id BIGINT       NOT NULL REFERENCES claim (id),
    seq      INT          NOT NULL,
    status   VARCHAR(20)  NOT NULL,
    by_user  VARCHAR(200) NOT NULL,
    on_date  DATE         NOT NULL,
    due      DECIMAL(19, 2),
    PRIMARY KEY (claim_id, seq)
);
-- V32__person_hold.sql
-- A person may have several holds over time, each from a date and, optionally, to a date (both
-- inclusive). While a hold covers an OPEN or PENDING claim's date, and no statement bound it, the
-- claim counts in no live total. A person held before holds were dated keeps a hold from the
-- beginning of time (no from-date) with no end.
CREATE TABLE person_hold (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- V33__rate_to.sql
-- A rate can carry a to-date: the last day it applies (none: it applies on for good). A claim dated
-- after the to-date of the rate that would apply to it has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
-- V34__sheet_cap.sql
-- The sheet's cap: the most a person's due-total can be (two decimals); none means no cap.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(15, 2) CHECK (due_cap >= 0);
-- V35__period_person_total.sql
-- Closing a period fixes each person's due-total for it too, as it was then; reopening clears them.
-- A person with no row here shows 0.00 for a closed period.
CREATE TABLE period_person_total (
    period_id BIGINT        NOT NULL REFERENCES period (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    total     DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- V36__sheet_setting_dated.sql
-- Settings that carry a figure are dated: each save records its value from a from-date, and the value in force
-- on a date is the one with the latest from-date on or before it. Keys: floor, late-pct, terms, terms-<grade>,
-- clerk-limit, cap. A value of none (blank) means no limit, no cap, or a grade using the sheet's terms.
-- Before every from-date the floor is 1.00, the late percent 0.00 and the terms 14; the others are none.
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);

-- The values a sheet already holds keep applying on every date, as they did before they were dated.
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;

DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
-- V37__claim_deferred.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches it,
-- the claim counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- V38__claim_proofs.sql
-- A claim's proofs count, raised by one at a time. A claim whose due is above the sheet's proof threshold
-- (a dated setting, key proof-threshold; none: no threshold) in force on its date cannot be settled or
-- approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- V39__sheet_permission.sql
-- The permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles that may do
-- it, as a comma separated list. An action with no row keeps the standing rule: open, settle, void and close
-- by clerk and steward; reassign and reopen by steward. Not dated.
CREATE TABLE sheet_permission (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    action   VARCHAR(20)  NOT NULL,
    roles    VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
-- V40__role_viewer.sql
-- A third role, viewer: sees the sheet and changes nothing. The role's check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200)  NOT NULL,
    role      VARCHAR(20)   NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
ALTER TABLE sheet_role ALTER COLUMN id RESTART WITH (SELECT COALESCE(MAX(id), 0) + 1 FROM sheet_role);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
-- V41__sheet_grace_days.sql
-- The sheet's grace days: when the sheet's today changes, every open period whose to-date plus the grace days
-- is before the new today is closed. None means off. Not dated.
ALTER TABLE sheet ADD COLUMN grace_days INTEGER CHECK (grace_days >= 0);
-- V42__claim_split_from.sql
-- The number of the claim a claim was split from; none for a claim that was not split off another.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(220);
-- V43__person_watch.sql
-- The users watching a person, each at most once; the id orders them by when they started watching.
CREATE TABLE person_watch (
    id        BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX person_watch_unique ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- V44__delegation.sql
-- A steward's delegation of the steward role to a user name, for a from-date to a to-date, inclusive, by the
-- sheet's today. While the sheet's today is inside the range the user acts as a steward for the delegator.
CREATE TABLE delegation (
    id        BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    delegator VARCHAR(200) NOT NULL,
    user_name VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX delegation_sheet_user ON delegation (sheet_id, user_name);
-- V45__sheet_archived.sql
-- An archived sheet: everything stays visible and every change is refused. Set by a steward, never undone.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- V46__person_terms.sql
-- A person may have their own terms: their claims are due that many days after their date, ahead of
-- their grade's terms and the sheet's. None (null) when they have no terms of their own.
ALTER TABLE person ADD COLUMN terms INT CHECK (terms >= 0);
-- V47__claim_locked_by.sql
-- The user whose editor is open on a claim, locking it for every other user until they save or cancel
-- it, or the sheet's today changes; none while unlocked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
-- V48__period_soft_close.sql
-- A period can be soft-closed: its due-total and each person's figure for it are fixed as on a close,
-- but claims dated inside it can still be added, edited, opened, settled and voided. A claim added
-- while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
-- V49__entity_version.sql
-- Each change to a sheet, its people, their claims and its rates keeps the state it left the row in, with
-- the sheet's today when it was made (none for a row removed), so a statement can be taken as of a date:
-- the rows as the changes made while the sheet's today was on or before it left them. Oldest first (by id).
-- Rows changed before this was kept have no versions.
CREATE TABLE entity_version (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL,
    kind        VARCHAR(20)  NOT NULL,
    entity_id   VARCHAR(200) NOT NULL,
    recorded_on DATE         NOT NULL,
    state       CLOB
);
CREATE INDEX entity_version_sheet ON entity_version (sheet_id, kind, recorded_on);
-- V50__sheet_entry_date.sql
-- The sheet's entry date: while set, the default date of a new claim in place of the sheet's today. None
-- (blank) means off. Not dated.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
-- V51__claim_reminded.sql
-- The last day (the sheet's today then) a reminder was written for a claim; none when never reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- V52__holiday.sql
-- The sheet's holidays: a claim whose date plus its terms falls on one is due by the next day that is not one,
-- by the holidays on the sheet when the claim is added. A date is on a sheet's list at most once.
CREATE TABLE holiday (
    id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL,
    UNIQUE (sheet_id, holiday_date)
);
-- V54__claim_ref.sql
-- A claim's external reference: unique on its sheet without regard to case; none when not given.
ALTER TABLE claim ADD COLUMN ref VARCHAR(200);
-- V55__claim_tags.sql
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; none when not given.
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000);

-- Every tag ever used on a sheet's claims, once each: the sheet shows a due-total for each.
CREATE TABLE sheet_tag (
    id       BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(2000) NOT NULL,
    UNIQUE (sheet_id, tag)
);
-- V56__void_reason.sql
-- The sheet's void reasons: while a sheet has any, a claim is voided with one of them. A reason is on a
-- sheet's list at most once. A voided claim keeps the reason it was voided with; none when voided without.
CREATE TABLE void_reason (
    id       BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(200) NOT NULL,
    UNIQUE (sheet_id, reason)
);

ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
-- V57__claim_comment.sql
-- Each claim's comments: one line per comment, in the order written, with the user who wrote it and the
-- sheet's today when it was written. Existing claims start with none.
CREATE TABLE claim_comment (
    claim_id BIGINT        NOT NULL REFERENCES claim (id),
    seq      INT           NOT NULL,
    by_user  VARCHAR(200)  NOT NULL,
    on_date  DATE          NOT NULL,
    comment_text VARCHAR(1000) NOT NULL,
    PRIMARY KEY (claim_id, seq)
);
-- V58__claim_edited_by.sql
-- Who last edited a claim: the signed-in user who last saved it through the claim form or the row's
-- amount entry. None while never edited. That user cannot settle or approve it (four eyes).
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(200);
-- V60__settle_batch.sql
-- Settle batches: a bulk settle that settles at least one claim (PENDING included) is a batch, numbered
-- 1, 2, ... on its sheet. A claim keeps the number of the batch that settled it; none when settled one at
-- a time, or never settled. The sheet keeps the number of its last batch; 0 before the first.
ALTER TABLE claim ADD COLUMN settle_batch INT;
ALTER TABLE sheet ADD COLUMN last_settle_batch INT NOT NULL DEFAULT 0;
-- V61__person_contact.sql
-- A person may have a contact, stored trimmed and lower-cased; none (null) when they have none. A
-- contact is unique on the sheet: the index refuses a second person with it.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
-- V62__person_alias.sql
-- A person may have aliases, each stored trimmed. An alias shares the names' uniqueness on the sheet,
-- compared without regard to case: alias_key is the alias as compared, and the index refuses a second
-- alias with it (an alias equal to a name is refused by the service).
CREATE TABLE person_alias (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(alias))
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
CREATE INDEX person_alias_person ON person_alias (person_id);
-- V63__claim_template.sql
-- The sheet's claim templates: a name (once per sheet), and the amount and note a claim made from it takes
-- at that moment. Saving a name again replaces its amount and note; claims made from it keep theirs.
CREATE TABLE claim_template (
    id       BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200)  NOT NULL,
    amount   NUMERIC(15,2) NOT NULL,
    note     VARCHAR(1000) NOT NULL,
    UNIQUE (sheet_id, name)
);
-- V64__pool.sql
-- The sheet's pools: a name (trimmed, once per sheet) and members, each a person of the sheet with a share
-- percent (more than 0.00, at most 100.00). A person is in a pool at most once, and may be in several pools.
CREATE TABLE pool (
    id       BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    UNIQUE (sheet_id, name)
);

CREATE TABLE pool_member (
    id        BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     NUMERIC(5,2) NOT NULL CHECK (share > 0 AND share <= 100),
    UNIQUE (pool_id, person_id)
);
-- V65__sheet_pot.sql
-- The sheet's pot: shared out among the members of each balanced pool by their shares. None means no pot.
-- Not dated.
ALTER TABLE sheet ADD COLUMN pot NUMERIC(15,2) CHECK (pot >= 0);
-- V66__sheet_parent.sql
-- The sheet's parent: a grade with no rate in force on a date on this sheet takes the parent's, then the
-- parent's parent's, up to three levels up. None means no parent. Not dated.
ALTER TABLE sheet ADD COLUMN parent VARCHAR(200) REFERENCES sheet (id);
-- V67__claim_deleted.sql
-- A DRAFT claim can be deleted (DELETED), counting nowhere, and restored to DRAFT on the sheet's today it
-- was deleted. The status check is re-made with it.
ALTER TABLE claim ALTER COLUMN status RENAME TO status_old;
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAF

