        } else if (entity instanceof Statement statement) {
            sheetId = statement.getSheetId();
            entityId = String.valueOf(statement.getId());
        } else if (entity instanceof Patron patron) {
            sheetId = patron.getSheetId();
            entityId = String.valueOf(patron.getId());
        } else if (entity instanceof Watch watch) {
            sheetId = watch.getSheetId();
            entityId = String.valueOf(watch.getId());
        } else if (entity instanceof SheetRole role) {
            sheetId = role.getSheetId();
            entityId = String.valueOf(role.getId());
        } else if (entity instanceof Delegation delegation) {
            sheetId = delegation.getSheetId();
            entityId = String.valueOf(delegation.getId());
        } else {
            throw new IllegalArgumentException("No history kept of " + entity.getClass());
        }
        LocalDate today = entity instanceof Sheet sheet ? sheet.getToday()
                : jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId).stream()
                        .filter(Objects::nonNull).findFirst().map(Date::toLocalDate).orElse(null);
        if (today == null) {
            return;
        }
        jdbc.update("INSERT INTO entity_version (sheet_id, kind, entity_id, recorded_on, state) VALUES (?, ?, ?, ?, ?)",
                sheetId, entity.getClass().getSimpleName(), entityId, Date.valueOf(today), state);
    }

    /** The sheet's rows of a kind as of a date, by id in the order first kept: each one's latest version made
     *  while the sheet's today was on or before it; none for a row removed then or not yet made. */
    public <T> Map<String, T> asOf(Class<T> type, String sheetId, LocalDate date) {
        Map<String, String> latest = new LinkedHashMap<>();
        jdbc.query("SELECT entity_id, state FROM entity_version WHERE sheet_id = ? AND kind = ? AND recorded_on <= ?"
                + " ORDER BY id", rs -> {
                    latest.put(rs.getString(1), rs.getString(2));
                }, sheetId, type.getSimpleName(), Date.valueOf(date));
        Map<String, T> rows = new LinkedHashMap<>();
        latest.forEach((id, state) -> {
            if (state != null) {
                rows.put(id, json.readValue(state, type));
            }
        });
        return rows;
    }

    /** The sheet's rows of a kind as of a date, in the order first kept. */
    public <T> List<T> listAsOf(Class<T> type, String sheetId, LocalDate date) {
        return List.copyOf(asOf(type, sheetId, date).values());
    }

    /** A row as of a date; none when it was not made by then, or removed. */
    public <T> Optional<T> findAsOf(Class<T> type, String sheetId, Object id, LocalDate date) {
        return Optional.ofNullable(asOf(type, sheetId, date).get(String.valueOf(id)));
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The request attribute naming the steward a user delegated the steward role acts for: each line of a
     *  change they make ends with for=<steward>, but for the lines that only report figures. */
    public static final String ACTING_FOR = Audit.class.getName() + ".actingFor";

    /** The events that only report figures, and so carry no for=. */
    private static final String[] FIGURES = { "ROLLUP ", "TOTALS ", "ALERT " };

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back (by any rule) writes nothing. Outside a transaction the record is written now.
     */
    public void recordOnCommit(String line) {
        String entry = line + actingFor(line);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    private static String actingFor(String entry) {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
        if (steward == null) {
            return "";
        }
        for (String figures : FIGURES) {
            if (entry.startsWith(figures)) {
                return "";
            }
        }
        return " for=" + steward;
    }

    /** Every record the file holds now, in the order written (none when there is no file yet). */
    public synchronized List<String> lines() {
        try {
            if (!Files.exists(file)) {
                return List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

