                    + " VALUES (?, ?, ?, ?, ?, ?)", poolIds.get(((Number) m.get("pool_id")).longValue()),
                    mapped(personIds, m.get("person_id")), mapped(poolIds, m.get("member_pool_id")), m.get("share"),
                    m.get("from_date"), m.get("to_date"));
